<script setup lang="ts">
import {onMounted,ref} from 'vue';
import {api} from '../core/http';
import {useAccountStore} from '../stores/account';
import AppHeader from '../components/AppHeader.vue';
import GuideLink from '../components/GuideLink.vue';
import {requirePrivacyReview} from '../services/privacyGuard';
const account=useAccountStore(),items=ref<any[]>([]),error=ref(''),message=ref(''),busy=ref(false),title=ref(''),text=ref(''),consent=ref(false),query=ref(''),result=ref<any>(null),file=ref<File|null>(null);
async function load(){if(!account.signedIn)return;try{items.value=await api('/api/v1/knowledge/documents')}catch(e:any){error.value=e.message}}
onMounted(load);
async function save(){if(!consent.value)return;busy.value=true;error.value='';try{const guard=await requirePrivacyReview(text.value,file.value?[file.value]:[],'',consent.value);if(guard.unchecked_sources.length&&!window.confirm('该文件未端侧识别，请确认已人工核对隐私并同意后端处理。'))return;let saved:any;if(file.value){const form=new FormData();form.append('file',file.value);form.append('title',title.value||file.value.name);form.append('consent','true');saved=await api('/api/v1/knowledge/documents',{method:'POST',body:form})}else saved=await api('/api/v1/knowledge/text',{method:'POST',body:JSON.stringify({title:title.value,text:text.value,consent:true})});if(saved.status!=='indexed')throw Error('资料已保留，但索引未完成：'+(saved.error_code||'待重试'));message.value='资料已进入当前账户知识库。';text.value='';file.value=null;consent.value=false;await load()}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function search(){busy.value=true;error.value='';try{result.value=await api('/api/v1/knowledge/ask',{method:'POST',body:JSON.stringify({query:query.value})})}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function remove(id:string){if(!window.confirm('删除知识索引？原件与已确认关联的事项证据会保留。'))return;try{await api('/api/v1/knowledge/documents/'+id,{method:'DELETE'});result.value=null;await load()}catch(e:any){error.value=e.message}}
</script>
<template><div class="page page--utility"><AppHeader title="知识资料库"/><GuideLink topic="knowledge" label="知识资料导入与来源检索说明"/><div v-if="error" class="notice notice--danger" role="alert">{{error}}</div><p v-if="message" role="status">{{message}}</p><p v-if="!account.signedIn">请先登录，资料按账户隔离。</p><template v-else><form class="surface-card form-card" @submit.prevent="save"><label>资料标题<input v-model="title" required maxlength="300"></label><label>资料正文<textarea v-model="text" rows="5" :required="!file"></textarea></label><label>或导入文件<input type="file" accept=".txt,.pdf,.docx,.png,.jpg,.jpeg,.xlsx,.xls" @change="file=($event.target as HTMLInputElement).files?.[0]||null"></label><label class="consent-row"><input v-model="consent" type="checkbox">我已人工核对资料隐私，同意保存到当前账户知识库。本地检索不发送给远程模型。</label><button class="button button--primary" :disabled="busy||!consent">导入知识资料</button></form><section class="surface-card"><h2>已导入资料</h2><article v-for="item in items" :key="item.id"><strong>{{item.title}}</strong> · {{item.status}} <button class="text-button" type="button" @click="remove(item.id)">删除索引</button></article><p v-if="!items.length">知识库尚无资料，系统不会用Demo资料代替。</p></section><form class="surface-card form-card" @submit.prevent="search"><label>查询校内规则<input v-model="query" required maxlength="4000"></label><button class="button button--secondary" :disabled="busy">查询来源片段</button></form><section v-if="result" class="surface-card"><p>当前使用本地检索与原文摘录，匹配分数不代表资格或正确率。</p><p v-if="!result.sources.length">{{result.answer}}</p><article v-for="source in result.sources" :key="source.id"><h3>{{source.title}}</h3><blockquote>{{source.quote}}</blockquote><small>来源片段 {{source.id}} · {{source.reference?.locator}}</small></article></section></template></div></template>
